        '<path d="M260 280v-65q0-100 140-110 140 10 140 110v65z" fill="#254d39"/><path d="M235 280h330v25H235z" fill="#a08445"/><path d="M320 135l130 145h-75L280 175z" fill="#a08445"/>',
